export function resolveMood(q, explicitMood) {
  if (explicitMood && MOOD_PATTERNS[explicitMood]) {
    return explicitMood;
  }
  if (!q) return null;
  const lower = q.toLowerCase().trim();
  if (PROMPT_TO_MOOD[lower]) return PROMPT_TO_MOOD[lower];
  if (MOOD_PATTERNS[lower]) return lower;

  // Check if string directly matches or contains a keyword in MOOD_PATTERNS
  for (const [moodKey, keywords] of Object.entries(MOOD_PATTERNS)) {
    for (const kw of keywords) {
      if (
        lower === kw ||
        lower.startsWith(kw + " ") ||
        lower.endsWith(" " + kw) ||
        lower.includes(" " + kw + " ")
      ) {
        return moodKey;
      }
    }
  }
  return null;
}

export function getCuratedRecommendations(queryText = "", typeFilter = "all", limit = 150, languageFilter = "all", explicitMood = null, suggestionLabel = null) {
  const q = (queryText || "").toLowerCase().trim();
  const lang = (languageFilter || "all").toLowerCase().trim();
  const targetMood = resolveMood(q, explicitMood);

  // Normalize language matching for both movies & songs
  const matchesLanguage = (item) => {
    if (lang === "all") return true;
    const itemLang = (item.language || "").toLowerCase();
    const itemInd = (item.industry || "").toLowerCase();

    if (lang === "hindi" || lang === "bollywood") {
      return itemLang.includes("hindi") || itemInd.includes("bollywood");
    }
    if (lang === "punjabi") {
      return itemLang.includes("punjabi") || itemInd.includes("punjabi");
    }
    if (lang === "english" || lang === "hollywood") {
      return itemLang.includes("english") || itemInd.includes("hollywood");
    }
    if (lang === "south-indian" || lang === "south") {
      return (
        itemInd.includes("south") ||
        ["tamil", "telugu", "malayalam", "kannada"].some(l => itemLang.includes(l))
      );
    }
    if (lang === "korean" || lang === "k-pop") {
      return itemLang.includes("korean") || itemInd.includes("k-pop") || itemInd.includes("world");
    }
    if (lang === "spanish" || lang === "latin") {
      return itemLang.includes("spanish") || itemInd.includes("latin") || itemInd.includes("world");
    }
    if (lang === "instrumental") {
      return itemLang.includes("instrumental") || itemInd.includes("soundtrack");
    }
    if (lang === "world" || lang === "international") {
      return (
        itemInd.includes("world") ||
        itemInd.includes("latin") ||
        itemInd.includes("k-pop") ||
        ["korean", "japanese", "french", "spanish", "german", "italian", "cantonese"].some(l => itemLang.includes(l))
      );
    }
    return itemLang.includes(lang) || itemInd.includes(lang);
  };

  // If no query and no mood, return highest rated in requested language & type
  if (!q && !targetMood) {
    const seen = new Set();
    return CURATED_MEDIA
      .filter(item => (typeFilter === "all" || item.type === typeFilter) && matchesLanguage(item))
      .filter(item => {
        const norm = (item.title || "").toLowerCase().replace(/[^a-z0-9]/g, "");
        if (seen.has(norm)) return false;
        seen.add(norm);
        return true;
      })
      .sort((a, b) => (b.rating || 0) - (a.rating || 0))
      .slice(0, limit);
  }

  // 1. IF A MOOD WAS REQUESTED OR DETECTED:
  if (targetMood) {
    const seen = new Set();
    const matchingItems = CURATED_MEDIA.filter(item => {
      if (typeFilter !== "all" && item.type !== typeFilter) return false;
      if (!matchesLanguage(item)) return false;
      
      const itemMoods = item.moods || [];
      // STRICT REQUIREMENT: Item MUST have this mood!
      if (!itemMoods.includes(targetMood)) return false;

      // Disallow conflicting moods unless it's a true hybrid
      const conflicts = MOOD_CONFLICTS[targetMood] || [];
      if (itemMoods.some(m => conflicts.includes(m)) && !itemMoods.includes(targetMood)) {
        return false;
      }

      // Deduplicate titles
      const norm = (item.title || "").toLowerCase().replace(/[^a-z0-9]/g, "");
      if (seen.has(norm)) return false;
      seen.add(norm);

      return true;
    });

    // Check if user specified suggestions or keywords (beyond the default generic mood prompt)
    const isGenericDefaultPrompt = Boolean(PROMPT_TO_MOOD[q] || q === targetMood);
    const textTokens = isGenericDefaultPrompt 
      ? [] 
      : q.split(/[\s,+/&-]+/).filter(t => t.length > 2 && t !== targetMood);
    const cleanLabel = (suggestionLabel || "").toLowerCase().replace(/[^\w\s]/g, " ").trim();
    const labelTokens = cleanLabel 
      ? cleanLabel.split(/\s+/).filter(t => t.length > 2 && t !== targetMood)
      : [];
    const suggestionTokens = [...new Set([...textTokens, ...labelTokens])];

    // Score within the mood for best ordering (primary tag bonus + rating + suggestion boost)
    const scored = matchingItems.map(item => {
      let score = (item.rating || 7.5) * 10;
      if (item.moods && item.moods[0] === targetMood) score += 25;

      const itemTitle = (item.title || "").toLowerCase();
      const itemCreator = (item.creator || "").toLowerCase();
      const itemCast = (item.cast || "").toLowerCase();
      const itemGenre = (item.genre || "").toLowerCase();
      const itemVibe = (item.vibe || "").toLowerCase();
      const itemBlurb = (item.blurb || "").toLowerCase();
      const itemReason = (item.reason || "").toLowerCase();
      const itemText = `${itemTitle} ${itemGenre} ${itemVibe} ${itemBlurb} ${itemReason} ${itemCast} ${itemCreator}`;

      // When specific suggestions or query keywords are active, boost matching items heavily
      if (suggestionTokens.length > 0) {
        // Exact query substring bonus
        if (cleanLabel && itemText.includes(cleanLabel)) score += 350;
        if (itemTitle.includes(q)) score += 350;
        if (itemGenre.includes(q)) score += 220;
        if (itemVibe.includes(q)) score += 180;
        if (itemCast.includes(q)) score += 150;
        if (itemCreator.includes(q)) score += 120;
        if (itemBlurb.includes(q)) score += 80;
        if (itemReason.includes(q)) score += 100;

        // Individual suggestion token bonuses
        for (const token of suggestionTokens) {
          if (itemTitle.includes(token)) score += 90;
          if (itemVibe.includes(token)) score += 75;
          if (itemGenre.includes(token)) score += 65;
          if (itemReason.includes(token)) score += 50;
          if (itemBlurb.includes(token)) score += 40;
          if (itemCast.includes(token)) score += 40;
          if (itemCreator.includes(token)) score += 35;
        }
      }

      // Add deterministic tie-breaker based on suggestion and item ID
      // so that non-matching items also shuffle and vary between suggestions
      const seedStr = (suggestionLabel || q || targetMood) + (item.id || item.title);
      let hash = 0;
      for (let i = 0; i < seedStr.length; i++) {
        hash = ((hash << 5) - hash) + seedStr.charCodeAt(i);
        hash |= 0;
      }
      score += (Math.abs(hash) % 15);

      return { item, score };
    });

    return scored
      .sort((a, b) => b.score - a.score)
      .map(s => s.item)
      .slice(0, limit);
  }

  // 2. IF FREEFORM TEXT SEARCH (Actor, Director, Title, Custom keyword):
  const scored = CURATED_MEDIA.map(item => {
    if (typeFilter !== "all" && item.type !== typeFilter) return { item, score: -100 };
    if (!matchesLanguage(item)) return { item, score: -100 };

    const itemTitle = (item.title || "").toLowerCase();
    const itemCreator = (item.creator || "").toLowerCase();
    const itemCast = (item.cast || "").toLowerCase();
    const itemGenre = (item.genre || "").toLowerCase();
    const itemVibe = (item.vibe || "").toLowerCase();
    const itemBlurb = (item.blurb || "").toLowerCase();
    const itemReason = (item.reason || "").toLowerCase();

    let textScore = 0;
    if (itemTitle === q) textScore += 300;
    else if (itemTitle.startsWith(q)) textScore += 180;
    else if (itemTitle.includes(q)) textScore += 100;

    if (itemCast.includes(q)) textScore += 60;
    if (itemCreator.includes(q)) textScore += 50;
    if (itemGenre.includes(q)) textScore += 40;
    if (itemVibe.includes(q)) textScore += 35;
    if (itemBlurb.includes(q)) textScore += 20;
    if (itemReason.includes(q)) textScore += 25;

    const tokens = q.split(/[\s,+/&-]+/).filter(t => t.length > 2);
    for (const token of tokens) {
      if (itemTitle.includes(token)) textScore += 25;
      if (itemCast.includes(token)) textScore += 20;
      if (itemCreator.includes(token)) textScore += 18;
      if (itemGenre.includes(token)) textScore += 15;
      if (itemVibe.includes(token)) textScore += 12;
    }

    if (textScore < 10) return { item, score: -100 };
    return { item, score: textScore + ((item.rating || 7) * 2) };
  });

  const seenFreeform = new Set();
  const uniqueScored = [];
  for (const s of scored.filter(s => s.score > 0).sort((a, b) => b.score - a.score)) {
    const norm = (s.item.title || "").toLowerCase().replace(/[^a-z0-9]/g, "");
    if (!seenFreeform.has(norm)) {
      seenFreeform.add(norm);
      uniqueScored.push(s.item);
    }
  }

  return uniqueScored.slice(0, limit);
}
